-- Business process maps (BPM): each unit can follow its own process. Steps run in a line with approve/return gates; cases are runs of a process.
create table if not exists process_defs (
  id uuid primary key default gen_random_uuid(),
  unit_id uuid references org_units(id) on delete cascade,
  code text, name text not null, kind text not null default 'operational' check (kind in ('planning','operational')),
  objective text, owner_title text, status text not null default 'active' check (status in ('draft','active','archived')),
  source text, copied_from uuid references process_defs(id) on delete set null, sort int default 0,
  created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists process_steps (
  id uuid primary key default gen_random_uuid(),
  process_id uuid not null references process_defs(id) on delete cascade,
  no text not null, name text not null, actor text, description text,
  is_gate boolean not null default false, gate_question text,
  next_no text, yes_no text, no_no text, sla_days int, sort int default 0,
  unique (process_id, no));
create table if not exists process_kpis (
  id uuid primary key default gen_random_uuid(),
  process_id uuid not null references process_defs(id) on delete cascade,
  name text not null, description text, formula text, unit text, target text, period text, source text, sort int default 0);
create table if not exists process_cases (
  id uuid primary key default gen_random_uuid(),
  process_id uuid not null references process_defs(id) on delete cascade,
  unit_id uuid references org_units(id) on delete cascade,
  title text not null, ref text, fiscal_year text default '2026/27',
  current_no text, status text not null default 'open' check (status in ('open','done','cancelled')),
  owner_position_id uuid references positions(id) on delete set null,
  deliverable_id uuid references deliverables(id) on delete set null,
  note text, started_at timestamptz default now(), step_started_at timestamptz default now(), closed_at timestamptz, created_by uuid default auth.uid());
create table if not exists process_case_log (
  id uuid primary key default gen_random_uuid(),
  case_id uuid not null references process_cases(id) on delete cascade,
  step_no text, action text not null check (action in ('start','done','yes','no','return','cancel','reopen','note')),
  to_no text, note text, by_user uuid default auth.uid(), by_name text, at timestamptz default now());
create index if not exists process_steps_p on process_steps(process_id);
create index if not exists process_cases_p on process_cases(process_id, status);
create index if not exists process_log_c on process_case_log(case_id, at);

alter table process_defs enable row level security; alter table process_steps enable row level security; alter table process_kpis enable row level security;
alter table process_cases enable row level security; alter table process_case_log enable row level security;
create or replace function public.in_unit(u uuid) returns boolean language sql stable security definer set search_path = public as
  $$ select public.is_group_admin() or exists(select 1 from positions p where p.user_id = auth.uid() and p.unit_id = u) $$;
grant execute on function public.in_unit(uuid) to authenticated;
do $$ declare t text; begin
  foreach t in array array['process_defs','process_steps','process_kpis','process_cases','process_case_log'] loop
    execute format('drop policy if exists %I_r on %I', t, t);
    execute format('create policy %I_r on %I for select to authenticated using (public.has_position())', t, t);
    execute format('grant select, insert, update, delete on %I to authenticated', t);
  end loop; end $$;
-- definitions: group admins and the unit's planners / heads
drop policy if exists process_defs_w on process_defs;
create policy process_defs_w on process_defs for all to authenticated using (public.is_group_admin() or public.can_plan_unit(unit_id)) with check (public.is_group_admin() or public.can_plan_unit(unit_id));
drop policy if exists process_steps_w on process_steps;
create policy process_steps_w on process_steps for all to authenticated
  using (exists(select 1 from process_defs d where d.id = process_id and (public.is_group_admin() or public.can_plan_unit(d.unit_id))))
  with check (exists(select 1 from process_defs d where d.id = process_id and (public.is_group_admin() or public.can_plan_unit(d.unit_id))));
drop policy if exists process_kpis_w on process_kpis;
create policy process_kpis_w on process_kpis for all to authenticated
  using (exists(select 1 from process_defs d where d.id = process_id and (public.is_group_admin() or public.can_plan_unit(d.unit_id))))
  with check (exists(select 1 from process_defs d where d.id = process_id and (public.is_group_admin() or public.can_plan_unit(d.unit_id))));
-- cases: anyone in the unit (or a group admin) can run them
drop policy if exists process_cases_w on process_cases;
create policy process_cases_w on process_cases for all to authenticated using (public.in_unit(unit_id)) with check (public.in_unit(unit_id));
drop policy if exists process_case_log_w on process_case_log;
create policy process_case_log_w on process_case_log for all to authenticated
  using (exists(select 1 from process_cases c where c.id = case_id and public.in_unit(c.unit_id)))
  with check (exists(select 1 from process_cases c where c.id = case_id and public.in_unit(c.unit_id)));

