'Assesses how well each strategy aligns with the organization’s vision, mission, and values','%','Annually','CEO/CCP Officer Feedback Reports'),('strategy-formulation','Completeness of Strategic Analysis','Tracks whether all required analyses (SWOT, PESTEL, Financial Forecast, etc.) were fully completed.','Count','Annually','Strategic Assessment Reports'),('strategy-formulation','Stakeholder Engagement Rate','Monitors participation of key departments or individuals during the strategy formulation workshops and reviews','%','Annually','Attendance Sheets, Meeting Records'),('strategy-evaluation','Evaluation report accuracy rate','Measures the percentage of evaluation reports accepted without requiring major revisions.',null,'Annually','ERP'),('strategy-evaluation','Average approval cycle time','Tracks the average time taken from submission of the evaluation report to final approval.','Days','Annually','ERP'),('risk-identification','Risk Identification Coverage','Measures the percentage of organizational units that have identified risks','%','Quarterly','Risk Register'),('risk-identification','Risk Response Implementation Rate','Measures how many approved responses are implemented on time','%','Quarterly','Risk Action Plans'),('risk-identification','Residual Risk Reduction','Measures reduction between initial and residual risk scores','Score','Semi-annual','Risk Reports'),('risk-identification','Risk Review Timeliness','Measures timeliness of risk review and updates','%','Quarterly','Risk Registry'),('risk-identification','Management Approval Cycle Time','Measures time taken to approve risk decisions','Days','Monthly','Approval Records')) as v(code,name,descr,unit,period,src) join process_defs d on d.code=v.code and d.unit_id='56bdc553-5f16-5df4-be26-a996e0de5165';
